const { ref } = Vue

const STORAGE_KEY = 'solar_term_festival_info'

/**
 * 节气产品树数据管理
 * @param {Function} fetchFn - 请求数据的函数，需返回 Promise<{code, data}>
 *   例：() => ajaxPromise(url, {key: 'solar_term_festival_info'})
 *   例：() => ajaxPromise({url, method, data})
 */
export function useSolrTerm(fetchFn) {
  const solrTermTree = ref([])
  const keyMap = {} // unique_key -> id
  const idToKeys = {} // id -> [unique_key, ...]

  function buildKeyMap(nodes) {
    nodes.forEach(node => {
      // 没有 unique_key 的节点用 id 兜底
      if (!node.unique_key) node.unique_key = node.id
      keyMap[node.unique_key] = node.id
      if (!idToKeys[node.id]) idToKeys[node.id] = []
      idToKeys[node.id].push(node.unique_key)
      if (node.children) buildKeyMap(node.children)
    })
  }

  async function getSolrTerm(force = false) {
    if (!force) {
      const cached = localStorage.getItem(STORAGE_KEY)
      if (cached) {
        const data = JSON.parse(cached)
        solrTermTree.value = data
        buildKeyMap(data)
        return
      }
    }
    const res = await fetchFn()
    if (res.code === 200) {
      const data = JSON.parse(res.data)
      solrTermTree.value = data
      buildKeyMap(data)
      localStorage.setItem(STORAGE_KEY, res.data)
    }
  }

  // unique_key[] -> id[] (提交给后端)
  function toIds(keys) {
    if (!keys?.length) return keys
    return keys.map(k => keyMap[k] || k)
  }

  // id[] -> unique_key[] (旧数据兼容回显)
  function toUniqueKeys(ids) {
    if (!ids?.length) return ids
    return ids.flatMap(v => {
      if (keyMap[v]) return [v] // 已经是 unique_key
      return idToKeys[v] || [v] // 旧的 id，展开为所有对应 unique_key
    })
  }

  return { solrTermTree, getSolrTerm, toIds, toUniqueKeys }
}

